 const method=h(Card,{title:'Implemented score definition'},h('div',{className:'card-body'},
  h('p',{className:'definition'},'Eligible suppliers only: 25% quality + 20% price + 20% delivery + 20% reliability + 15% evidence coverage − 15% risk.'),
  h('div',{className:'pill-note'},'Illustrative, unlearned weights. Price is min–max normalized within the component. Quality = 100 − 10 × defect %. Delivery = 100 × (20 − lead days) / 20, clipped to 0–100. Reliability is the latest on-time-delivery percentage.'),
  h('p',{className:'definition'},'Risk = 65% delivery-failure percentage + 35% scaled defects, weighted by recent month. Records older than 120 days are excluded. Evidence coverage includes satisfied and violated known states; it is not a compliance rate.')));
 const checks=h(Card,{title:'Scenario checks',sub:'Internal checks against handcrafted expected decisions, not research accuracy results.',className:'alignment',action:h(Button,{primary:true,onClick:()=>setRun(true)},run?'Run again':'Run checks')},
  h(SimpleTable,{head:['CHECK','EXPECTED ELIGIBLE','STATUS','SCENARIO'],rows:tests.map(t=>[t.name,t.expected.join(', ')||'None',run?h(Tag,{tone:JSON.stringify(t.actual)===JSON.stringify(t.expected)?'green':'red'},JSON.stringify(t.actual)===JSON.stringify(t.expected)?'Passed':'Failed'):h(Tag,null,'Not run'),h('button',{className:'linkbtn',onClick:()=>onScenario(t.scenario)},'Open scenario ↗')])}));
 const experiments=[['Vector RAG vs hybrid RAG','Recall@5, MRR, nDCG'],['Structured ranking vs RAG + ranking vs RESA','nDCG and expert agreement'],['Claim verification','Supported claims / verifiable claims'],['Ablations: no alignment, risk or verification','Change in ranking and unsupported-claim rate']];
 const plan=h(Card,{title:'Experimental evaluation plan',sub:'No model benchmark results have been generated yet.',className:'alignment'},h(SimpleTable,{head:['EXPERIMENT','WHAT TO MEASURE','STATE'],rows:experiments.map(r=>[...r,h(Tag,null,'Planned')])}),h('div',{className:'footnote'},'Use independently reviewed labels and held-out supplier/time splits. Do not use the scoring formula as its own ground truth.'));
 const benchmark=h(Card,{title:'Public retrieval benchmark',sub:data.benchmark.length+' development queries · expected parts are source annotations',className:'alignment'},
  h('div',{className:'card-body'},h('input',{className:'search',value:q,onChange:e=>setQ(e.target.value),'aria-label':'Search benchmark',placeholder:'Try “brake”, “Swift” or “engine”…'})),
  h(SimpleTable,{head:['QUERY','TYPE','EXPECTED PARTS','DIFFICULTY'],rows:queries.slice(0,12).map(r=>[r.query,r.query_type,r.expected_parts.join(', '),h(Tag,null,r.difficulty)])}),
  h('div',{className:'footnote'},`Showing ${Math.min(12,queries.length)} of ${queries.length} matches. This is a query inspector, not a running retriever.`));
 const boundary=h(Card,{title:'Implementation boundary',className:'alignment'},h('div',{className:'card-body definition'},'This first-review dashboard uses React with loaded CSV/JSON snapshots, deterministic requirement checks and source-linked explanations. The agreed research stack remains the target: Unstructured + Camelot, nomic-embed-text/Ollama, LlamaIndex, Qdrant, Llama 3.1 8B, FastAPI, PostgreSQL, MinIO, Redis and Docker. Those services are not running inside this sample dashboard.'));
 return h(React.Fragment,null,intro,h('div',{className:'about-grid'},contribution,method),checks,plan,benchmark,boundary);
