function Drawer({doc,onClose}){
 const ref=useRef(null);
 useEffect(()=>{const prev=document.activeElement;ref.current?.focus();const fn=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const els=[...ref.current.querySelectorAll('button,a[href]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',fn);return()=>{document.removeEventListener('keydown',fn);prev?.focus();};},[]);
 return h('div',{className:'modal-backdrop',onClick:e=>{if(e.target===e.currentTarget)onClose();}},h('aside',{className:'drawer',role:'dialog','aria-modal':true,'aria-label':'Evidence record',tabIndex:-1,ref},h('div',{className:'drawer-top'},h('div',null,h('div',{className:'eyebrow'},'SOURCE EVIDENCE'),h('h2',null,doc.title)),h('button',{className:'close','aria-label':'Close evidence',onClick:onClose},'×')),h('div',{className:'dataset-meta'},h(Tag,{tone:'amber'},'Synthetic review record'),h(Tag,null,doc.type)),h('blockquote',null,doc.excerpt),h('dl',null,...Object.entries({'Record ID':doc.id,'Supplier ID':doc.supplier_id||'Scenario policy','Record date':doc.date,'Source':doc.provenance}).flatMap(([k,v])=>[h('dt',{key:k},k),h('dd',{key:k+'v'},v)])),h('p',{className:'pill-note'},'This is a structured demo record, not an uploaded corporate document. It is linked by exact supplier and record IDs. No vector retrieval or LLM verification is claimed.'),h(Button,{onClick:()=>download(doc.id+'.json',JSON.stringify(doc,null,2))},h(Icon,{name:'download'}),'Download this record')));
}
